def make_t(lang: str):
    table = STR.get(lang, EN)

    def t(key: str, **kw) -> str:
        s = table.get(key) or EN.get(key, key)
        return s.format(**kw) if kw else s

    return t


def ex_name(ex, lang: str) -> str:
    return EX_AR.get(ex.id, ex.name) if lang == "ar" else ex.name


def muscle_name(muscle: str, lang: str) -> str:
    return MUSCLE_AR.get(muscle, muscle) if lang == "ar" else muscle.title()


def day_label(name: str, lang: str) -> str:
    if lang != "ar":
        return name
    for en, ar in _DAY_AR.items():
        if name.startswith(en):
            return ar + name[len(en):]
    return name
